def count_vowels(s):
    """Count vowels in s, ignoring case. 'y' counts as a vowel at the end of a word."""
    vowels = set('aeiou')
    count = 0
    s = s.lower()
    for i, char in enumerate(s):
        if char in vowels:
            count += 1
        elif char == 'y':
            # Check if 'y' is at the end of the string or followed by a non-word character
            if i == len(s) - 1 or not s[i + 1].isalnum():
                count += 1
    return count
